Method.Implementation:
	 #dim status as %Status
	 set status = $$$OK
	 $$$TRACE("$$$$$ Inside OnMessage method <"_pRequest.StringValue_">")	 
	 try {		 
		set result = ..objCdrTuxService.checkMmi(pRequest.StringValue)
		if ('$isObject(result)){
	   		$$$TRACE(">>>>> Response is not an object")
       		set status = $System.Status.Error($$$GeneralError,"CheckMMI returned a null reference")
       		quit
		}		
		set pResponse = ##class(Ens.StringRequest).%New()  
 		set pResponse.StringValue = result
	 } catch err {	 
	 	$$$TRACE("Exception in calling CheckMmi; AsSystemError is: " _err.AsSystemError() _ ";$ZERROR: " _ $ZERROR _ ";ErrName: " _ $ZCVT(err.Name,"O","HTML")_ "; ErrData: " _ err.Data _ "; ErrCode:" _ err.Code _ "ErrLocation:" _ err.Location)	    

	    set status = $$$ERROR("Exception in calling CheckMmi " _ err.Data)		    	     	 

	    if errText["CONNECTIONERROR"{		   
		   set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError($CLASSNAME(),errText)
	    }	    
	    if errText["RESEND"{
		   set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError($CLASSNAME(),errText)
	    }
	    if errText["DATAERROR"{
		   set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError($CLASSNAME(),errText)
	    }
	    if errText["SHUTDOWN"{
		   set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError($CLASSNAME(),errText)
	    }
	 }
	 return status


do ##super()
$$$TRACE("$$$$$ Inside OnInit() method...")	
#dim status as %Status
set status = $$$OK	
$$$TRACE("OnInit..JarFile "_ ..JarFile)
do ..JavaGateway.%Import(..JarFile) 	 

 try{
	set ..objCdrTuxService = ##class(org.ihc.itf.cdr.CdrReadMmi).%New(..JavaGateway,..ApplicationAddress, ..TuxedoService)

}catch err{
	$$$TRACE("Exception while Creating Tuxedo Service: " _err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)
    set status=$$$ERROR(" Exception while initializing Tuxedo Service: "_err.AsSystemError()_"::"_err.Data_"::"_err.Code)

}
quit status

$$$TRACE(" $$$$$ Inside OnTearDown() method...")
set tSC = $$$OK

try {		
	if $IsObject(..objCdrTuxService) {
		$$$TRACE("Disconnecting from CDR Tuxedo service...")
		do ..objCdrTuxService.shutdownTuxService()			
		set ..objCdrTuxService = $$$NULLOREF
	}
} catch {
	set tSC = $$$EnsSystemError
}
set tSC = ##super()
quit tSC
